<?php
require_admin();
header('Cache-Control: private, no-store');
require_once __DIR__.'/login_notice_store.php';
$allNotices=cds_ln_all();$editId=is_string($_GET['edit']??null)?$_GET['edit']:null;
$notice=isset($_GET['new'])?cds_ln_defaults():cds_ln_load($editId);$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
    if(!hash_equals(cds_ln_csrf(),(is_string($_POST['csrf']??null)?$_POST['csrf']:''))){http_response_code(403);exit('Phiên làm việc không hợp lệ.');}
    try{
        if(($_POST['notice_action']??'save')==='delete'){
            cds_ln_delete(is_string($_POST['id']??null)?$_POST['id']:'',is_string($_POST['version']??null)?$_POST['version']:'',current_user());
            flash('Đã xóa thông báo.','success');header('Location: '.BASE_URL.'admin.php?view=login_notice');exit;
        }
        if(($_POST['notice_action']??'save')!=='save')throw new RuntimeException('Thao tác không hợp lệ.');
        $saved=cds_ln_save($_POST,current_user());flash('Đã lưu thông báo và lịch hiển thị.','success');
        header('Location: '.BASE_URL.'admin.php?view=login_notice&edit='.urlencode($saved['id']));exit;
    }catch(RuntimeException $e){
        $error=$e->getMessage();
        if(($_POST['notice_action']??'save')==='save'){
            $notice=cds_ln_load(is_string($_POST['id']??null)?$_POST['id']:'');
            foreach(['title','body','icon','theme'] as $key)$notice[$key]=is_string($_POST[$key]??null)?$_POST[$key]:'';
            $notice['enabled']=!empty($_POST['enabled']);
        }
    }
}
