<?php if(!$allNotices):?><tr><td colspan="5" class="text-center text-muted py-4">Chưa có thông báo. Bấm Thêm thông báo hoặc soạn nội dung bên dưới.</td></tr><?php endif;foreach($allNotices as $row):
