$state=empty($row['enabled'])?'Đang tắt':($expired?'Đã hết hạn':($planned?'Chờ đến lịch':'Đang hiển thị'));$badge=empty($row['enabled'])?'secondary':($expired?'light text-dark border':($planned?'warning text-dark':'success'));
?><tr class="<?=$row['id']===$notice['id']?'table-primary':''?>"><td style="min-width:200px"><span class="me-1"><?=e($row['icon'])?></span><strong><?=e($row['title']?:'Chưa đặt tiêu đề')?></strong></td><td><span class="badge bg-<?=$badge?>"><?=$state?></span></td><td class="small text-nowrap"><?=e($row['starts_at']!==''?str_replace('T',' ',cds_ln_date_input($row['starts_at'])):'Ngay khi bật')?></td><td class="small text-nowrap"><?=e($row['ends_at']!==''?str_replace('T',' ',cds_ln_date_input($row['ends_at'])):'Đến khi tắt')?></td><td><div class="d-flex justify-content-end gap-2"><a class="btn btn-sm btn-outline-primary" href="<?=e(BASE_URL)?>admin.php?view=login_notice&edit=<?=urlencode($row['id'])?>#lnSettingsForm">Sửa</a><form method="post" onsubmit="return confirm('Xóa thông báo này? Thao tác không thể hoàn tác.');"><input type="hidden" name="csrf" value="<?=e(cds_ln_csrf())?>"><input type="hidden" name="notice_action" value="delete"><input type="hidden" name="id" value="<?=e($row['id'])?>"><input type="hidden" name="version" value="<?=e($row['version'])?>"><button class="btn btn-sm btn-outline-danger">Xóa</button></form></div></td></tr><?php endforeach;?></tbody></table></div><div class="ln-help mt-3">Nếu nhiều thông báo cùng có hiệu lực, hệ thống hiển thị lần lượt theo thời gian bắt đầu. Mỗi tài khoản chỉ cần đóng từng thông báo một lần.</div></section>
